 clear(p){for(const r of this.enemies.values())if(r.phase!=='defeated'&&r.section.index>=this.nav.state.index){if(this.nav.y<.22&&circlesTouchBody(profileOf(this.nav,.70),p,this.nav.heading,r,r.spec.radius))return false;const q=courseCoordinates(r.section,p);if(Math.abs(q.lateral)<4&&q.s>r.spec.gateS-bodyExtent(profileOf(this.nav),this.nav.heading,r.section.forward)&&q.s<r.section.length+4)return false;}return true;}
