 requestAttack({ranged=false,target:picked=null}={}){const n=this.nav;if(this.attack||this.cooldown>0||n.recovery>0||n.jumpStage==='anticipation')return false;const airborne=!n.grounded&&n.y>.08;let target=picked&&picked.phase!=='defeated'?picked:this.current;if(picked)this.focusId=picked.id;const spec=elementalAttack(n.partner),range=ranged?spec.range:2.0+n.radius;if(target&&target.phase!=='defeated'&&distance(n.player,target)<range+1.0){const heading=Math.atan2(target.x-n.player.x,target.z-n.player.z);n.heading=heading;n.events.face?.(heading);}else target=null;if(ranged&&!target){const section=n.trials?.blocking,record=section&&n.trials.record(section),nodes=section?.trial?.nodes.filter((_,i)=>!record.broken.includes(i))||[],node=nodes.sort((a,b)=>distance(a,n.player)-distance(b,n.player))[0];if(node&&distance(node,n.player)<=range){n.heading=Math.atan2(node.x-n.player.x,node.z-n.player.z);n.events.face?.(n.heading);}}
  this.combo=n.courseTime-this.lastEnd<.4?(this.combo+1)%2:0;this.attack={id:++this.serial,kind:airborne?'jump':this.combo?'turn':'strike',age:0,duration:ranged?spec.windup+spec.recovery:airborne?.58:.48,ranged,element:spec.element,partner:n.partner||'hufflepuff',hit:false,heading:n.heading,origin:{...n.player}};n.stop();n.events.attack?.(this.attack);return true;
 }
 say(kind,r){this.lastFeedback={text:combatAdvice(kind,r),until:this.nav.courseTime+2.4};}
 phase(r,name,duration){r.phase=name;r.timer=0;r.duration=duration;r.returning=false;}
 resetEnemy(r){r.x=r.spec.x;r.z=r.spec.z;r.active=false;r.rings=[];r.cycles=0;this.phase(r,'watch',0);}
 retry(){this.lastFeedback=null;this.projectiles=[];this.attack=null;this.cooldown=.3;for(const r of this.enemies.values())if(r.phase!=='defeated')this.resetEnemy(r);}
 beginCharge(r){const n=this.nav,section=r.section,q=courseCoordinates(section,n.player);const s=Math.max(1.7,Math.min(section.length-2,q.s-1.0)),lateral=Math.max(-2.2,Math.min(2.2,q.lateral));r.chargeFrom={x:r.x,z:r.z};r.chargeTo=localPoint(section,s,lateral);r.heading=Math.atan2(r.chargeTo.x-r.x,r.chargeTo.z-r.z);this.phase(r,'windup',n.mode==='challenge'?.85:1.35);}
 prepare(r){if(r.spec.kind==='ram')this.beginCharge(r);else{r.heading=Math.atan2(this.nav.player.x-r.x,this.nav.player.z-r.z);this.phase(r,r.spec.kind==='seed'?'seedwindup':'sporewindup',this.nav.mode==='challenge'?1.1:1.6);}}
 recoverDuration(r,afterHit=false){const challenge=this.nav.mode==='challenge';return r.spec.kind==='seed'?(challenge?2.8:3.6):r.spec.kind==='spore'?(challenge?2.5:3.2):afterHit?(challenge?1:1.5):(challenge?1.55:2.3);}
