 // Brambleguard shrug a hit off. No circling behind, no instant blocks, so a group stays manageable.
 canDamage(r){return!['charge','seedstrike'].includes(r.phase);}
 damage(r,from=this.nav.player){const dx=r.x-from.x,dz=r.z-from.z,d=Math.hypot(dx,dz)||1;r.hitDirection={x:dx/d,z:dz/d};const n=this.nav;if(r.hp<=0)return;r.hp--;r.flash=.25;r.rings=[];const record=encounterRecord(n.state,r.spec);record.hp=r.hp;record.defeated=r.hp===0;if(record.defeated){r.active=false;this.phase(r,'defeated',1.1);n.events.defeat?.(r);}else{
  // A hit while it waits or recovers makes it flinch; a hit during its wind-up does not cancel the attack it is preparing.
  if(['watch','recover','hurt'].includes(r.phase))this.phase(r,'hurt',.28);n.events.combatSave?.();}this.say('hit',r);n.events.damaged?.(r);n.events.impact?.({x:r.x,z:r.z,y:.55},true);}
 attackStep(dt){const n=this.nav;this.cooldown=Math.max(0,this.cooldown-dt);if(!this.attack)return;const a=this.attack;a.age+=dt;if(!a.hit&&a.age>=(a.ranged?elementalAttack(a.partner).windup:a.kind==='jump'?.08:.18)){a.hit=true;if(a.ranged)this.launch(a);else{const r=this.current;if(r&&r.phase!=='defeated'&&distance(n.player,r)<=2.0+n.radius&&(a.kind==='jump'||n.y<1.2)){if(this.canDamage(r,a))this.damage(r);else{r.guardAge=0;this.say('blocked',r);n.events.impact?.({x:r.x,z:r.z,y:.55},false);}}else if(!n.trials?.strike(a))n.events.swing?.(a);}}if(a.age>=a.duration){this.lastEnd=n.courseTime;this.attack=null;this.cooldown=Math.max(this.cooldown,.12);}}
 launch(a){const n=this.nav,spec=elementalAttack(a.partner),origin={x:n.player.x,z:n.player.z,y:n.y+Math.min(.9,n.height*.55)};a.origin={...origin};const p={id:a.id,partner:a.partner,element:spec.element,heading:a.heading,kind:a.kind,origin:{...origin},x:origin.x,z:origin.z,y:origin.y,distance:0,spec};this.projectiles.push(p);n.events.projectile?.(p);}
 projectileStep(dt){const n=this.nav;this.projectiles=this.projectiles.filter(p=>{if(n.recovery>0)return false;const remaining=p.spec.range-p.distance,travel=Math.min(remaining,p.spec.speed*dt),from={x:p.x,z:p.z},to={x:p.x+Math.sin(p.heading)*travel,z:p.z+Math.cos(p.heading)*travel};let collision=null;const candidate=(t,kind,target)=>{if(t!==null&&(!collision||t<collision.t))collision={t,kind,target};};
  for(const solid of n.solids||[])if(p.y<(solid.top||4)+p.spec.radius)candidate(segmentHit(from,to,solid,solid.r+p.spec.radius),'solid',solid);
  for(const r of this.group)if(r.phase!=='defeated'&&p.y<1.8)candidate(segmentHit(from,to,r,r.spec.radius+p.spec.radius),'enemy',r);
  const section=n.trials?.blocking,record=section&&n.trials.record(section);for(const [index,node]of (section?.trial?.nodes||[]).entries())if(!record.broken.includes(index)&&p.y<1.8)candidate(segmentHit(from,to,node,.42+p.spec.radius),'crystal',{section,node,index});
  const fraction=collision?.t??1;p.x=from.x+(to.x-from.x)*fraction;p.z=from.z+(to.z-from.z)*fraction;p.distance+=travel*fraction;
  if(collision){if(collision.kind==='enemy'){const a={kind:p.kind,ranged:true,origin:p.origin};if(this.canDamage(collision.target,a))this.damage(collision.target,p.origin);else{collision.target.guardAge=0;this.say('blocked',collision.target);p.blocked=true;n.events.impact?.({x:p.x,y:p.y,z:p.z},false);}}else if(collision.kind==='crystal'){const before=n.trials.record(collision.target.section).hp;n.trials.strikeNode(collision.target.index);p.blocked=n.trials.record(collision.target.section).hp===before;}n.events.projectileImpact?.(p,collision.kind);return false;}
  if(p.distance>=p.spec.range-1e-6){n.events.projectileImpact?.(p,'miss');return false;}return true;});}
 beginPulse(r){r.cycles++;r.rings=[];r.emitted=0;r.pulseCount=this.nav.mode==='challenge'?2:1;r.pulseSpeed=this.nav.mode==='challenge'?3.35+r.section.area*.12:2.7;r.ringInterval=jumpTuning(this.nav.level).ringInterval;this.phase(r,'pulse',9/r.pulseSpeed+(r.pulseCount-1)*r.ringInterval);this.emitRing(r);}
 emitRing(r){r.rings.push({id:r.cycles+':'+r.emitted,radius:.62,previousRadius:.62,width:.15,maxRadius:9});r.emitted++;}
 pulseStep(r,dt){const n=this.nav;if(r.emitted<r.pulseCount&&r.timer>=r.emitted*r.ringInterval)this.emitRing(r);const interval=bodyDistanceInterval(profileOf(n,.30),n.player,n.heading,r);for(const ring of r.rings){ring.previousRadius=ring.radius;ring.radius+=r.pulseSpeed*dt;const margin=ring.width/2;if(n.invincible<=0&&n.y<.24&&interval.max>=ring.previousRadius-margin&&interval.min<=ring.radius+margin){n.retry('spore-ring');return;}}r.rings=r.rings.filter(ring=>ring.radius<ring.maxRadius);if(r.timer>=r.duration){r.rings=[];this.phase(r,'recover',this.recoverDuration(r));}}
 seedStep(r){const n=this.nav;if(r.phase==='seedwindup'&&r.timer>=r.duration){this.phase(r,'seedstrike',.44);r.slamHit=false;}else if(r.phase==='seedstrike'){if(!r.slamHit&&r.timer>=.14){r.slamHit=true;const d=distance(n.player,r),dot=((n.player.x-r.x)*Math.sin(r.heading)+(n.player.z-r.z)*Math.cos(r.heading))/(d||1);if(n.invincible<=0&&circlesTouchBody(profileOf(n,.30),n.player,n.heading,r,r.slamRange)&&dot>Math.cos(r.slamHalfAngle+Math.asin(Math.min(.8,bodyExtent(profileOf(n,.30),n.heading,{x:Math.cos(r.heading),z:-Math.sin(r.heading)})/(d||1))))&&n.y<.9){n.retry('leaf-slam');return;}}if(r.timer>=r.duration)this.phase(r,'recover',this.recoverDuration(r));}}
